// Change these, then save. The form and the webhook can send their own
// location, intent signal, lookback hours, runs, target and sub-areas; what
// they leave out comes from here. "Execute workflow" uses these values as is.

// --- what to look for ---
const LOCATION = 'Austin, Texas';
const INTENT_SIGNAL = 'announced a new funding round';
const LOOKBACK_HOURS = 96; // a source older than this is rejected
const RUNS = 50; // how many search angles to plan (your "50 chats")
const TARGET = 40; // stop as soon as this many new companies are found
const SUB_AREAS = ''; // optional, comma separated: 'Downtown, East Austin, Round Rock'. Empty = generic areas.

// --- the model ---
// An API that speaks the OpenAI Responses format with the built-in web search
// tool. The key is in the credential "Account Scanner Model".
const MODEL_BASE_URL = 'https://api.openai.com/v1'; // without /responses
const MODEL = 'gpt-6-astra'; // any model that supports the web_search tool
const STRUCTURED_OUTPUT = true; // send the JSON schema with the request. Set to false if your server rejects "text.format".
// Is the source the model names a page its web search really returned?
//   'url'    the exact page must be among the citations or sources of the answer
//   'domain' its website must be among them
//   'off'    do not check
const CITED_SOURCE_CHECK = 'url';

// --- pace ---
const CONCURRENCY = 5; // model calls at the same time. Each batch gets the companies found by the batches before it.
const PAUSE_BETWEEN_BATCHES_SECONDS = 0;
const MAX_ATTEMPTS = 3; // tries per angle when the API says "too many requests" or is down
const RETRY_WAIT_SECONDS = 10; // doubled per attempt; a Retry-After header from the API wins
const MAX_WAIT_SECONDS = 60;
const EXCLUDE_LIST_MAX = 200; // how many known companies the prompt lists (newest first). Dedupe always checks all of them.
const MAX_RUNS = 200;

// ---------------------------------------------------------------------------
const first = $input.first().json ?? {};
const raw = first.body && typeof first.body === 'object' ? first.body : first;
const sent = {};
for (const [key, value] of Object.entries(raw)) sent[key.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '')] = value;
// The form hands over an empty number field as 0: that means "not filled in".
const fromForm = 'submittedAt' in first || 'formMode' in first;
const given = (value) => value !== undefined && value !== null && String(value).trim() !== '' && !(fromForm && value === 0);
const pick = (...names) => {
  for (const name of names) if (given(sent[name])) return sent[name];
  return undefined;
};
const text = (value, fallback) => String(value ?? fallback).trim();
const number = (value, fallback) => (value === undefined ? fallback : Number(value));

return [
  {
    json: {
      location: text(pick('location'), LOCATION),
      intent_signal: text(pick('intent_signal', 'signal'), INTENT_SIGNAL),
      lookback_hours: number(pick('lookback_hours', 'lookback'), LOOKBACK_HOURS),
      runs: number(pick('runs', 'number_of_runs'), RUNS),
      target: number(pick('target', 'target_count'), TARGET),
      sub_areas: text(pick('sub_areas'), SUB_AREAS),
      concurrency: number(pick('concurrency'), CONCURRENCY),
      model_base_url: MODEL_BASE_URL.replace(/\/+$/, ''),
      model: MODEL,
      structured_output: STRUCTURED_OUTPUT,
      cited_source_check: CITED_SOURCE_CHECK,
      pause_seconds: PAUSE_BETWEEN_BATCHES_SECONDS,
      max_attempts: MAX_ATTEMPTS,
      retry_wait_seconds: RETRY_WAIT_SECONDS,
      max_wait_seconds: MAX_WAIT_SECONDS,
      exclude_list_max: EXCLUDE_LIST_MAX,
      max_runs: MAX_RUNS,
    },
  },
];

// Plans the run: N search angles that all differ, and what is already known
// from earlier runs. One item comes out: the state that travels round the loop.
//
// An angle is one value from each list below. The lists have 4, 25, 9 and 7
// entries, numbers that share no divisor, so angle 1, 2, 3 ... change in every
// respect at once and no combination repeats before 6,300 angles. Edit the
// lists to fit your market; any lengths work, the planner skips repeats.

const AREAS = (location) => [
  `anywhere in ${location}`,
  `the centre of ${location}`,
  `the outskirts, suburbs and business parks of ${location}`,
  `smaller towns and districts in and around ${location}`,
];
const INDUSTRIES = [
  'software and SaaS', 'healthcare and medical practices', 'manufacturing', 'construction and building trades', 'retail and e-commerce',
  'financial services and fintech', 'logistics and transport', 'food and beverage', 'professional services (legal, accounting, consulting)', 'real estate and property',
  'energy and utilities', 'education and training', 'hospitality, travel and leisure', 'biotech and life sciences', 'media, marketing and advertising',
  'telecoms and IT services', 'automotive and mobility', 'agriculture and food production', 'non-profits and public sector suppliers', 'consumer goods',
  'hardware, electronics and robotics', 'insurance', 'security and defence', 'sports, fitness and wellness', 'any industry not usually in the news',
];
const SOURCES = [
  'local and regional news sites', 'press release wires', "the company's own newsroom or blog", 'LinkedIn posts by the company or its leaders', 'trade and industry publications',
  'business journals and startup news', 'job boards and careers pages', 'public filings, registries and government notices', 'newsletters, podcasts and community forums',
];
const WORDINGS = (signal) => [
  `${signal}`,
  `an official announcement of: ${signal}`,
  `news coverage reporting: ${signal}`,
  `a founder or executive writing about: ${signal}`,
  `early signs (job ads, filings, permits, supplier notices) of: ${signal}`,
  `the same thing described in other words or in the local language: ${signal}`,
  `a customer, partner or investor mentioning: ${signal}`,
];

// How two answers are recognised as the same company. Shared by "Plan angles"
// and "Read answers" (scripts/build.mjs copies it into both).
//   domainKey('https://www.Acme.io/about') -> 'acme.io'
//   nameKey('ACME, Inc.')                  -> 'acme'
// A profile on a shared site (LinkedIn, Crunchbase, ...) is not a company
// website, so it gives no domain key and the name decides.
const SHARED_HOSTS = ['linkedin.com', 'facebook.com', 'x.com', 'twitter.com', 'instagram.com', 'youtube.com', 'tiktok.com', 'crunchbase.com', 'wikipedia.org', 'google.com', 'medium.com', 'substack.com', 'github.com', 'linktr.ee', 'bit.ly', 'wordpress.com', 'blogspot.com', 'wixsite.com', 'notion.site', 'glassdoor.com', 'indeed.com', 'yelp.com', 'bloomberg.com', 'pitchbook.com'];
const SITE_PREFIXES = ['www', 'www2', 'careers', 'jobs', 'blog', 'news', 'newsroom', 'press', 'investors', 'ir', 'about', 'shop', 'store', 'app', 'en', 'm'];
const LEGAL_WORDS = ['inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'plc', 'gmbh', 'ag', 'sa', 'sas', 'srl', 'bv', 'nv', 'ab', 'as', 'oy', 'pty', 'pte', 'lp', 'llp', 'group', 'holdings'];

function domainKey(website) {
  let host = String(website ?? '').trim().toLowerCase();
  host = host.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').split(/[/?#]/)[0].replace(/^.*@/, '').replace(/:\d+$/, '').replace(/\.$/, '');
  if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host)) return '';
  let labels = host.split('.');
  while (labels.length > 2 && SITE_PREFIXES.includes(labels[0])) labels = labels.slice(1);
  host = labels.join('.');
  if (SHARED_HOSTS.some((shared) => host === shared || host.endsWith(`.${shared}`))) return '';
  return host;
}

function nameKey(name) {
  const words = String(name ?? '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .split(' ')
    .filter(Boolean);
  while (words.length > 1 && LEGAL_WORDS.includes(words[words.length - 1])) words.pop();
  if (words.length > 1 && words[0] === 'the') words.shift();
  return words.join(' ');
}

const settings = $('Settings').first().json;
const whole = (value) => (Number.isFinite(value) ? Math.floor(value) : NaN);
const runs = whole(settings.runs);
const target = whole(settings.target);
const hours = Number(settings.lookback_hours);

let error = null;
if (!settings.location || !settings.intent_signal) error = 'location and intent_signal are required';
else if (!(runs >= 1)) error = 'runs must be 1 or more';
else if (!(target >= 1)) error = 'target must be 1 or more';
else if (!(hours > 0)) error = 'lookback_hours must be more than 0';

// --- the angles ---
const angles = [];
if (!error) {
  const own = settings.sub_areas.split(',').map((area) => area.trim()).filter(Boolean);
  const areas = own.length ? own.map((area) => `${area} (${settings.location})`) : AREAS(settings.location);
  const wordings = WORDINGS(settings.intent_signal);
  const used = new Set();
  const wanted = Math.min(runs, settings.max_runs);
  for (let i = 0; angles.length < wanted && i < wanted * 20; i++) {
    const angle = { area: areas[i % areas.length], industry: INDUSTRIES[i % INDUSTRIES.length], source: SOURCES[i % SOURCES.length], wording: wordings[i % wordings.length] };
    const key = [angle.area, angle.industry, angle.source, angle.wording].join('|');
    if (used.has(key)) continue;
    used.add(key);
    angles.push(angle);
  }
}

// --- what earlier runs found ---
const earlier = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row && row.company)
  .sort((a, b) => String(b.found_at ?? '').localeCompare(String(a.found_at ?? '')));
const domains = [];
const names = [];
for (const row of earlier) {
  const d = row.domain_key || domainKey(row.website);
  const n = row.name_key || nameKey(row.company);
  if (d) domains.push([d, 'earlier']);
  if (n) names.push([n, 'earlier', Boolean(d)]);
}

const concurrency = Math.max(1, Math.min(whole(settings.concurrency) || 1, 20));
const started = Date.now();
return [
  {
    json: {
      run_id: `${$now.toFormat('yyyyLLdd-HHmmss')}-${$execution.id}`,
      started_at: new Date(started).toISOString(),
      cutoff_at: new Date(started - hours * 3600 * 1000).toISOString(),
      settings: { ...settings, runs, target, lookback_hours: hours },
      error,
      angles,
      queue: angles.map((_, index) => index), // angles still to ask, by position
      attempts: {}, // angle position -> calls made
      concurrency,
      start_concurrency: concurrency,
      batch: 0,
      wait_seconds: 0,
      more: !error && angles.length > 0,
      stopped: error ? 'invalid_input' : null,
      earlier_count: earlier.length,
      exclude_earlier: earlier.slice(0, settings.exclude_list_max).map((row) => (row.domain_key ? `${row.company} (${row.domain_key})` : row.company)),
      domains,
      names,
      found: [],
      log: [],
      model_calls: 0,
      web_searches: 0,
      input_tokens: 0,
      output_tokens: 0,
      total_tokens: 0,
    },
  },
];

// Takes the next few angles from the queue and writes one request per angle.
// Every request lists the companies that are already known: those of earlier
// runs and those the batches before this one found. That list is what makes
// the later calls look somewhere new instead of returning the same names.
//
// The request follows OpenAI's Responses API with the built-in web search tool:
// https://developers.openai.com/api/docs/guides/tools-web-search
const state = $input.first().json;
const s = state.settings;

const exclude = [...state.found.map((row) => (row.domain_key ? `${row.company} (${row.domain_key})` : row.company)).reverse(), ...state.exclude_earlier].slice(0, s.exclude_list_max);

const SYSTEM = [
  'You find companies for a sales prospect list by searching the web.',
  'Always search the web before you answer. Never answer from memory.',
  'Report exactly one company, and only if a page you found in this search shows the signal. That page is your source: give its exact URL and the date it was published.',
  'If you find no company that fits, answer with an empty string in every field. An empty answer is better than a guess.',
  'Answer with one JSON object and nothing else: {"company": "", "website": "", "signal": "", "source_url": "", "source_date": ""}',
  "company: the company's name. website: its own website, not a social profile. signal: one sentence on what happened. source_url: the page that shows it. source_date: when that page was published, as YYYY-MM-DD or a full ISO 8601 time.",
].join('\n');

const SCHEMA = {
  type: 'object',
  properties: {
    company: { type: 'string' },
    website: { type: 'string' },
    signal: { type: 'string' },
    source_url: { type: 'string' },
    source_date: { type: 'string' },
  },
  required: ['company', 'website', 'signal', 'source_url', 'source_date'],
  additionalProperties: false,
};

const take = state.queue.slice(0, state.concurrency);
return take.map((index, position) => {
  const angle = state.angles[index];
  const prompt = [
    `Search angle ${index + 1} of ${state.angles.length}.`,
    `Find one company in ${s.location} with this signal: ${s.intent_signal}`,
    `The source must be published after ${state.cutoff_at} (the last ${s.lookback_hours} hours; it is now ${state.started_at}).`,
    `Where to look: ${angle.area}`,
    `Industry: ${angle.industry}`,
    `Kind of source: ${angle.source}`,
    `How the signal may show up: ${angle.wording}`,
    '',
    exclude.length ? 'Already on the list. Do not report these again, find a different company:' : 'Nothing is on the list yet.',
    ...exclude.map((entry) => `- ${entry}`),
  ].join('\n');

  const request = {
    model: s.model,
    input: [
      { role: 'system', content: SYSTEM },
      { role: 'user', content: prompt },
    ],
    tools: [{ type: 'web_search' }],
    tool_choice: 'required', // the search must run
    include: ['web_search_call.action.sources'], // every URL the search read, to check the source against
  };
  if (s.structured_output) request.text = { format: { type: 'json_schema', name: 'company_signal', schema: SCHEMA, strict: true } };

  return {
    json: {
      angle_index: index,
      attempt: (state.attempts[index] ?? 0) + 1,
      wait_seconds: state.wait_seconds,
      request,
      // The whole state rides on the first item, so "Read answers" can pick it up after the HTTP node.
      ...(position === 0 ? { state } : {}),
    },
  };
});

// Reads the answers of one batch, in the order they were asked, and decides
// per answer: found, rejected (with the reason), duplicate, or try again.
// One item comes out: the state for the next round.
//
// Response shape (OpenAI Responses API with web search):
//   output[]: { type: 'web_search_call', action: { type: 'search', sources: [{ url }] } }
//             { type: 'message', content: [{ type: 'output_text', text, annotations: [{ type: 'url_citation', url }] }] }
//   usage:    { input_tokens, output_tokens, total_tokens }
const batch = $('Next batch').all();
const answers = $input.all();
const state = JSON.parse(JSON.stringify(batch[0].json.state));
const s = state.settings;

// How two answers are recognised as the same company. Shared by "Plan angles"
// and "Read answers" (scripts/build.mjs copies it into both).
//   domainKey('https://www.Acme.io/about') -> 'acme.io'
//   nameKey('ACME, Inc.')                  -> 'acme'
// A profile on a shared site (LinkedIn, Crunchbase, ...) is not a company
// website, so it gives no domain key and the name decides.
const SHARED_HOSTS = ['linkedin.com', 'facebook.com', 'x.com', 'twitter.com', 'instagram.com', 'youtube.com', 'tiktok.com', 'crunchbase.com', 'wikipedia.org', 'google.com', 'medium.com', 'substack.com', 'github.com', 'linktr.ee', 'bit.ly', 'wordpress.com', 'blogspot.com', 'wixsite.com', 'notion.site', 'glassdoor.com', 'indeed.com', 'yelp.com', 'bloomberg.com', 'pitchbook.com'];
const SITE_PREFIXES = ['www', 'www2', 'careers', 'jobs', 'blog', 'news', 'newsroom', 'press', 'investors', 'ir', 'about', 'shop', 'store', 'app', 'en', 'm'];
const LEGAL_WORDS = ['inc', 'incorporated', 'llc', 'ltd', 'limited', 'corp', 'corporation', 'co', 'company', 'plc', 'gmbh', 'ag', 'sa', 'sas', 'srl', 'bv', 'nv', 'ab', 'as', 'oy', 'pty', 'pte', 'lp', 'llp', 'group', 'holdings'];

function domainKey(website) {
  let host = String(website ?? '').trim().toLowerCase();
  host = host.replace(/^[a-z][a-z0-9+.-]*:\/\//, '').split(/[/?#]/)[0].replace(/^.*@/, '').replace(/:\d+$/, '').replace(/\.$/, '');
  if (!/^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(host)) return '';
  let labels = host.split('.');
  while (labels.length > 2 && SITE_PREFIXES.includes(labels[0])) labels = labels.slice(1);
  host = labels.join('.');
  if (SHARED_HOSTS.some((shared) => host === shared || host.endsWith(`.${shared}`))) return '';
  return host;
}

function nameKey(name) {
  const words = String(name ?? '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .split(' ')
    .filter(Boolean);
  while (words.length > 1 && LEGAL_WORDS.includes(words[words.length - 1])) words.pop();
  if (words.length > 1 && words[0] === 'the') words.shift();
  return words.join(' ');
}

const DAY = 24 * 3600 * 1000;
const started = Date.parse(state.started_at);
const cutoff = Date.parse(state.cutoff_at);
const domains = new Map(state.domains.map(([key, where]) => [key, where]));
const names = new Map(state.names.map(([key, where, hasDomain]) => [key, { where, hasDomain }]));

// The JSON object in the answer text. Code fences, text around the JSON and a
// comma before a closing bracket are repaired; anything else is not usable.
function readJson(text) {
  const trimmed = String(text ?? '').trim();
  const attempts = [trimmed];
  const fenced = /```(?:json)?\s*([\s\S]*?)```/i.exec(trimmed)?.[1];
  if (fenced) attempts.push(fenced.trim());
  const body = fenced ?? trimmed;
  const from = body.search(/[{[]/);
  const to = Math.max(body.lastIndexOf('}'), body.lastIndexOf(']'));
  if (from !== -1 && to > from) attempts.push(body.slice(from, to + 1), body.slice(from, to + 1).replace(/,\s*([}\]])/g, '$1'));
  for (const attempt of attempts) {
    try {
      let value = JSON.parse(attempt);
      if (value && Array.isArray(value.companies)) value = value.companies;
      if (Array.isArray(value)) value = value[0] ?? {};
      if (value && typeof value === 'object') return value;
    } catch {
      /* try the next one */
    }
  }
  return null;
}

// A page address without the parts that differ between two links to the same page.
function pageKey(url) {
  const match = /^https?:\/\/([^/?#]+)([^?#]*)/i.exec(String(url ?? '').trim());
  if (!match) return '';
  return `${match[1].toLowerCase().replace(/^www\./, '')}${match[2].replace(/\/+$/, '')}`;
}
const hostOf = (url) => pageKey(url).split('/')[0];

// When the source was published, in milliseconds. A date without a time counts
// as the end of that day, so a source from the edge of the window is kept.
function publishedAt(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;
  const day = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (day) return Date.UTC(Number(day[1]), Number(day[2]) - 1, Number(day[3])) + DAY - 1;
  const time = Date.parse(text);
  if (Number.isNaN(time)) return null;
  return /\d:\d\d/.test(text) ? time : time + DAY - 1;
}

const clean = (value) => (typeof value === 'string' ? value.trim() : value === null || value === undefined ? '' : String(value).trim());

// Returns { outcome: 'found' | 'rejected' | 'duplicate', reason, row }
function judge(body, angle) {
  const output = Array.isArray(body?.output) ? body.output : [];
  const searches = output.filter((entry) => entry?.type === 'web_search_call');
  const parts = output.filter((entry) => entry?.type === 'message').flatMap((entry) => (Array.isArray(entry.content) ? entry.content : []));
  if (parts.some((part) => part?.type === 'refusal')) return { outcome: 'rejected', reason: 'refused' };
  const texts = parts.filter((part) => part?.type === 'output_text');
  const answer = readJson(texts.map((part) => part.text ?? '').join('\n'));
  if (!answer) return { outcome: 'bad_json' };

  const row = {
    company: clean(answer.company),
    website: clean(answer.website),
    signal: clean(answer.signal),
    source_url: clean(answer.source_url),
    source_date: clean(answer.source_date),
  };
  if (!row.company) return { outcome: 'rejected', reason: 'nothing_found', row };
  if (!/^https?:\/\/[^\s/]+\.[^\s/]+/i.test(row.source_url)) return { outcome: 'rejected', reason: 'no_source', row };

  if (s.cited_source_check !== 'off') {
    if (searches.length === 0) return { outcome: 'rejected', reason: 'no_web_search', row };
    const cited = [
      ...texts.flatMap((part) => (Array.isArray(part.annotations) ? part.annotations : [])).filter((note) => note?.type === 'url_citation').map((note) => note.url),
      ...searches.flatMap((search) => (Array.isArray(search.action?.sources) ? search.action.sources : [])).map((source) => source?.url),
    ].filter(Boolean);
    const ok = s.cited_source_check === 'domain' ? cited.some((url) => hostOf(url) === hostOf(row.source_url)) : cited.some((url) => pageKey(url) === pageKey(row.source_url));
    if (!ok) return { outcome: 'rejected', reason: 'source_not_in_search', row };
  }

  const published = publishedAt(row.source_date);
  if (published === null) return { outcome: 'rejected', reason: 'no_source_date', row };
  if (published < cutoff) return { outcome: 'rejected', reason: 'stale_source', row };
  if (published > started + 2 * DAY) return { outcome: 'rejected', reason: 'source_date_in_future', row };

  // Same company? The website's domain decides. The name decides only when
  // one of the two has no usable website.
  row.domain_key = domainKey(row.website);
  row.name_key = nameKey(row.company);
  let known = null;
  if (row.domain_key && domains.has(row.domain_key)) known = domains.get(row.domain_key);
  else if (row.name_key && names.has(row.name_key) && (!row.domain_key || !names.get(row.name_key).hasDomain)) known = names.get(row.name_key).where;
  if (known) return { outcome: 'duplicate', reason: known === 'earlier' ? 'found_in_earlier_run' : 'found_in_this_run', row };

  if (row.domain_key) domains.set(row.domain_key, 'run');
  if (row.name_key && !names.has(row.name_key)) names.set(row.name_key, { where: 'run', hasDomain: Boolean(row.domain_key) });
  row.angle = `${angle.area} · ${angle.industry} · ${angle.source} · ${angle.wording}`;
  return { outcome: 'found', row };
}

state.batch += 1;
let wait = 0;
let slowDown = false;
const again = [];
const asked = new Set();

answers.forEach((item, position) => {
  const entry = batch[position].json;
  const index = entry.angle_index;
  const angle = state.angles[index];
  asked.add(index);
  state.attempts[index] = entry.attempt;
  state.model_calls += 1;

  const status = item.json.statusCode;
  let body = item.json.body;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch {
      body = null;
    }
  }
  const usage = body?.usage ?? {};
  state.input_tokens += Number(usage.input_tokens) || 0;
  state.output_tokens += Number(usage.output_tokens) || 0;
  state.total_tokens += Number(usage.total_tokens) || (Number(usage.input_tokens) || 0) + (Number(usage.output_tokens) || 0);
  if (Array.isArray(body?.output)) state.web_searches += body.output.filter((part) => part?.type === 'web_search_call').length;

  const line = { angle: index + 1, batch: state.batch, attempt: entry.attempt };
  const retry = (reason, seconds) => {
    again.push(index);
    wait = Math.max(wait, seconds);
    state.log.push({ ...line, outcome: 'retry', reason });
  };
  const backoff = Math.min(s.retry_wait_seconds * 2 ** (entry.attempt - 1), s.max_wait_seconds);

  if (status === 429 || status === undefined || status >= 500) {
    // Too many requests, API down or not reachable: wait and ask again.
    const reason = status === 429 ? 'rate_limited' : status === undefined ? 'api_unreachable' : `api_error_${status}`;
    if (status === 429) slowDown = true;
    const header = Number(item.json.headers?.['retry-after']);
    const seconds = Number.isFinite(header) && header > 0 ? Math.min(header, s.max_wait_seconds) : backoff;
    if (entry.attempt < s.max_attempts) retry(reason, seconds);
    else state.log.push({ ...line, outcome: 'rejected', reason });
    return;
  }
  if (status !== 200) {
    // 400, 401, 403, 404: the request itself is wrong (key, model, address). Asking 49 more times will not help.
    state.fatal = `the model API answered HTTP ${status}${body?.error?.message ? `: ${String(body.error.message).slice(0, 200)}` : ''}`;
    state.log.push({ ...line, outcome: 'rejected', reason: `api_error_${status}` });
    return;
  }

  const verdict = judge(body, angle);
  if (verdict.outcome === 'bad_json') {
    // Not usable JSON: one more try, then give up on this angle.
    if (entry.attempt < Math.min(2, s.max_attempts)) retry('bad_json', 0);
    else state.log.push({ ...line, outcome: 'rejected', reason: 'bad_json' });
    return;
  }
  const note = { ...line, outcome: verdict.outcome };
  if (verdict.reason) note.reason = verdict.reason;
  if (verdict.row?.company) note.company = verdict.row.company;
  if (verdict.row?.source_url) note.source_url = verdict.row.source_url;
  if (verdict.row?.source_date) note.source_date = verdict.row.source_date;
  state.log.push(note);
  if (verdict.outcome === 'found') state.found.push({ ...verdict.row, angle_number: index + 1 });
});

// Angles to ask again go back to the front of the queue.
state.queue = [...again, ...state.queue.filter((index) => !asked.has(index))];
// After a "too many requests" the batches are half as big for the rest of the run.
if (slowDown) state.concurrency = Math.max(1, Math.floor(state.concurrency / 2));
state.wait_seconds = Math.max(wait, state.queue.length ? s.pause_seconds : 0);
state.domains = [...domains].map(([key, where]) => [key, where]);
state.names = [...names].map(([key, value]) => [key, value.where, value.hasDomain]);

if (state.fatal) state.stopped = 'api_error';
else if (state.found.length >= s.target) state.stopped = 'target_reached';
else if (state.queue.length === 0) state.stopped = 'angles_used_up';
state.more = !state.stopped;

return [{ json: state }];

// One item per new company: the row that is saved.
const state = $('Finish').first().json;
const s = state.settings;
return state.found.map((row) => ({
  json: {
    company: row.company,
    website: row.website,
    domain_key: row.domain_key,
    name_key: row.name_key,
    signal: row.signal,
    source_url: row.source_url,
    source_date: row.source_date,
    angle: row.angle,
    location: s.location,
    intent_signal: s.intent_signal,
    run_id: state.run_id,
    found_at: state.started_at,
  },
}));

// The columns that go to the sheet, in this order. Put the same names in row 1
// of your sheet. Remove a line here to leave a column out.
return $input.all().map((item) => ({
  json: {
    company: item.json.company,
    website: item.json.website,
    signal: item.json.signal,
    source_url: item.json.source_url,
    source_date: item.json.source_date,
    angle: item.json.angle,
    location: item.json.location,
    intent_signal: item.json.intent_signal,
    found_at: item.json.found_at,
    run_id: item.json.run_id,
  },
}));

// What the run did, counted from its log. Every model call is one log line,
// and every angle that was tried ends as found, rejected or duplicate, so:
//   model_calls  = angles_tried + retries
//   angles_tried = found + rejected + duplicates
const state = $('Finish').first().json;
const s = state.settings;
const count = (list) => list.reduce((totals, key) => ({ ...totals, [key]: (totals[key] ?? 0) + 1 }), {});

const final = state.log.filter((line) => line.outcome !== 'retry');
const rejected = final.filter((line) => line.outcome === 'rejected');
const duplicates = final.filter((line) => line.outcome === 'duplicate');
const retries = state.log.filter((line) => line.outcome === 'retry');
const found = state.found.length;
// Rows that came back from the save step (none when nothing was found).
const saved = $input.all().filter((item) => item.json && item.json.company).length;

const stoppedText = {
  target_reached: `stopped early: the target of ${s.target} was reached`,
  angles_used_up: 'all angles were tried',
  api_error: `stopped: ${state.fatal}`,
  invalid_input: `nothing was searched: ${state.error}`,
}[state.stopped];

return [
  {
    json: {
      ok: state.stopped === 'target_reached' || state.stopped === 'angles_used_up',
      run_id: state.run_id,
      ran_at: state.started_at,
      location: s.location,
      intent_signal: s.intent_signal,
      lookback_hours: s.lookback_hours,
      target: s.target,
      stopped: state.stopped,
      error: state.error ?? state.fatal ?? null,
      angles_planned: state.angles.length,
      angles_tried: final.length,
      angles_not_needed: state.angles.length - final.length,
      found,
      saved,
      rejected: rejected.length,
      rejected_why: count(rejected.map((line) => line.reason)),
      duplicates: duplicates.length,
      duplicates_why: count(duplicates.map((line) => line.reason)),
      retries: retries.length,
      retries_why: count(retries.map((line) => line.reason)),
      model_calls: state.model_calls,
      batches: state.batch,
      web_searches: state.web_searches,
      input_tokens: state.input_tokens,
      output_tokens: state.output_tokens,
      total_tokens: state.total_tokens,
      known_before: state.earlier_count,
      text: `${found} new ${found === 1 ? 'company' : 'companies'} from ${final.length} of ${state.angles.length} angles (${stoppedText}). Rejected ${rejected.length}, duplicates ${duplicates.length}, retries ${retries.length}. ${state.model_calls} model calls, ${state.total_tokens} tokens.`,
      companies: state.found.map((row) => ({ company: row.company, website: row.website, signal: row.signal, source_url: row.source_url, source_date: row.source_date, angle_number: row.angle_number })),
      log: state.log,
    },
  },
];
